import pytest
import torch

import flag_gems

from . import accuracy_utils as utils
from .test_linalg_svd import (
    _for_comparison,
    _from_numpy,
    _missing_cpu_lapack,
    _reference_input,
)


def _reference_cond(inp, p=None):
    try:
        return torch.linalg.cond(inp, p=p)
    except RuntimeError as error:
        if not _missing_cpu_lapack(inp, error):
            raise
    import numpy as np

    array = inp.detach().numpy()
    if p == "nuc":
        value = np.linalg.norm(array, ord="nuc", axis=(-2, -1)) * np.linalg.norm(
            np.linalg.inv(array), ord="nuc", axis=(-2, -1)
        )
    else:
        value = np.linalg.cond(array, p=p)
    return _from_numpy(value)


# Matrix shapes for linalg_cond tests
LINALG_COND_SHAPES = [(2, 2), (4, 4), (8, 8), (16, 16), (32, 32)]
LINALG_COND_SHAPES_SVD = [(2, 3), (4, 4), (4, 6), (8, 8), (16, 16)]

# Only float32 supported: Triton Jacobi SVD implementation uses float32
LINALG_COND_DTYPES = [torch.float32]

# Condition number is sensitive to numerical differences between GPU/CPU
# inverse implementations. Use relative tolerance based on matrix condition.
LINALG_COND_RTOL = 0.15


def _make_moderate_cond_matrix(shape, dtype, device):
    """Generate a matrix with moderate, bounded condition number.

    Adds a large diagonal to ensure the condition number stays
    in a predictable range, avoiding flaky test failures from ill-conditioned
    random matrices where GPU/CPU inverse differences get amplified.
    """
    torch.manual_seed(0)
    n = shape[-1]
    batch_shape = shape[:-2]
    A = torch.randn(shape, dtype=dtype, device=device)
    # Add n*I to keep condition number bounded at ~O(n)
    eye = torch.eye(n, dtype=dtype, device=device)
    for _ in batch_shape:
        eye = eye.unsqueeze(0)
    eye = eye.expand_as(A)
    A = A + n * eye
    return A


@pytest.mark.linalg_cond
@pytest.mark.parametrize("shape", LINALG_COND_SHAPES)
@pytest.mark.parametrize("dtype", LINALG_COND_DTYPES)
def test_linalg_cond(shape, dtype):
    # Test with p=None (2-norm via Jacobi SVD)
    A = _make_moderate_cond_matrix(shape, dtype, flag_gems.device)
    ref_A = _reference_input(A, True)

    ref_out = _reference_cond(ref_A)
    res_out = flag_gems.linalg_cond(A)

    # Use relative comparison for condition numbers
    utils.gems_assert_close(
        _for_comparison(res_out, ref_out, A), ref_out, dtype, atol=1.0
    )


